-- The session line below must be the coordinator's own session; written_by is read from it.
BEGIN;
SET LOCAL truth.session_id = '<COORDINATOR SESSION, registered to seat 36>';
WITH s AS (
INSERT INTO ask_aar_snapshots (ask, rev, title, objective, objective_met, objective_met_reason, objective_source, written_by, prior_row, operator_words, card, owner_seat, plan, build_files, revert, grades, md5_written, audit_ids, objects, tests, readbacks, run_evidence, manuals, status, sources)
VALUES (585, '0', 'ASK 585: a retried run sends Record Substitution the real debate',
  $t$When n8n retries a crashed execution, Record Substitution sends the real debate_id and substitution, not "{}". The 41147 failure ("odv1_record_panel_substitution without parameters", debate_errors a21bad71) cannot recur from a recovered placeholder. A normal run is unchanged. (plan rev 0, section 1, Wall 11275)$t$,
  'in part',
  $t$Written by W4 at 22:26 CST 2026-11-23, after run ODV1-42071-uclot7fi had ended, on the card "Write 585 after the run" pressed 22:25 CST in W4's thread (Wall 11286; audit 41068). Engine 9c9891d4 to 196402d0-8396-4e8d-b559-f2cf86eda863; one node changed, Alternate Merge, 581935a1 (16,364 characters) to 4a623df6 (16,428 characters): the line that takes Pass Accumulate now skips an item marked isArtificialRecoveredEventItem, so Alternate Merge 1's item is taken. Child f900375e unchanged; no model setting. W1 readback MATCH (Wall 11289). Not shown by a run: only a retry of a crashed execution takes the path, and no run is retried on purpose; the offline test t585.cjs shows the placeholder case (live code: undefined; patched: Alternate Merge 1's debate_id), run by W4 and again by W1. Limit stated in the plan: if Alternate Merge 1 is also only a placeholder, the run fails to Panel Failure Note as before.$t$,
  '10353, 11273, 11275, 11278, 11280, 11282, 11286, 11289',
  current_setting('truth.session_id'), NULL,
  to_jsonb($t$No sentence of the operator on ASK 585 is in the record W3 read. The fault was reported as still live by W4 at Wall 11273 (21:54 CST 2026-11-23), after W3's batch 1 manual draft had moved the manual's only mention of it to the log (corrected at Wall 11274); the coordinator assigned ASK 585 to W4 at 21:54 CST. The operator's part is the card press: "Write 585 after the run", 22:25 CST 2026-11-23, W4's thread (Wall 11286).$t$::text),
  $j${"answer": "Write 585 after the run", "source": "Wall 11286", "thread": "W4", "press_time": "22:25 CST", "question": "not in the record W3 read (the card is in W4's thread; Wall 11286 gives its label only)"}$j$::jsonb,
  'W4',
  $j${"md5": "0ad8885e", "note": "rev 0 with F1 met (the size line in characters); first posted as b7277064", "path": "a585_w4/plan585.md", "commit": "e92b9098", "source": "Wall 11275, 11280, 11282; not md5-checked by W3 (git only)"}$j$::jsonb,
  $j$[{"md5": "581935a1", "path": "a585_w4/build/alternate_merge_9c9891d4.js", "note": "Alternate Merge as live before, 16,364 characters", "source": "Wall 11275, 11278"}, {"md5": "4a623df6", "path": "a585_w4/build/alternate_merge_585.js", "note": "Alternate Merge with change E1, 16,428 characters; the node code written", "source": "Wall 11275, 11278, 11286, 11289"}, {"md5": "5e7d05b6", "path": "a585_w4/build/t585.cjs", "note": "offline test, three cases", "source": "Wall 11278"}, {"md5": "4bd2270d", "path": "a585_w4/build/out_t585.txt", "note": "its output", "source": "Wall 11278"}, {"md5": "53f685b4", "path": "ask585/w4/write/put_eng585.json", "note": "PUT body sent", "source": "md5sum by W3"}, {"md5": "28604493", "path": "ask585/w4/write/fetchback_eng585.json", "note": "fetch-back, versionId 196402d0 (W1 Wall 11289)", "source": "md5sum by W3; Wall 11289"}, {"md5": "3068ed90", "path": "ask585/w4/write/prewrite_eng585.json", "note": "fresh fetch before the write", "source": "md5sum by W3"}]$j$::jsonb,
  $j${"copy": "the saved prior engine, ask585/w4/write/revert_eng585.json 9281b5b1 (the same file md5 as ask584/w4/write/put_eng.json, the ASK 584 PUT body)", "path": "ask585/w4/write/revert_eng585.json", "source": "Wall 11286 item 4; md5sum by W3"}$j$::jsonb,
  $j$[{"seat": "W1", "verdict": "PASS WITH ONE CONDITION F1 (plan rev 0)", "wall_id": 11278, "md5_graded": "b7277064", "verdict_norm": "PASS", "source": "Wall 11278 head"}, {"seat": "W1", "verdict": "PASS (the built node alternate_merge_585.js: its md5 checked, its diff read, the test run by W1; Wall 11278 items 1 to 3)", "wall_id": 11278, "md5_graded": "4a623df6", "verdict_norm": "PASS", "source": "Wall 11278 items 1, 2, 3"}, {"seat": "W1", "verdict": "F1 MET, the grade stands as PASS (plan with the size line corrected)", "wall_id": 11282, "md5_graded": "0ad8885e", "verdict_norm": "PASS", "source": "Wall 11282"}]$j$::jsonb,
  ARRAY['4a623df6'], '[41068]'::jsonb,
  $j$[{"kind": "n8n workflow", "name": "ORACLE_DEBATE_V1 moMxiV4Irg1uRBZN", "after": "196402d0-8396-4e8d-b559-f2cf86eda863, active, 398 nodes", "before": "9c9891d4"}, {"kind": "n8n node", "name": "Alternate Merge (engine, Code)", "after": "4a623df6, 16,428 characters", "before": "581935a1, 16,364 characters"}, {"kind": "n8n workflow, unchanged", "name": "child MqQHRl7mQQ0z8QdT", "after": "f900375e", "before": "f900375e"}]$j$::jsonb,
  $j$[{"name": "t585.cjs, three cases on the live and the patched node code", "result": "(i) normal: same debate_id from Pass Accumulate on both; (ii) Pass Accumulate not run: from Alternate Merge 1 on both; (iii) recovered placeholder: live undefined (the fault reproduced), patched Alternate Merge 1's debate_id", "source": "Wall 11275 section 5; W1's own run Wall 11278 item 3"}, {"name": "C1 rerun on the built node before the PUT", "result": "case (iii) gives Alternate Merge 1's debate_id", "source": "Wall 11286 item 3"}, {"name": "C2 per-node diff of the fetch-back", "result": "only Alternate Merge changed, only E1", "source": "Wall 11286 item 2; W1 Wall 11289 items 1, 2"}, {"name": "C3 child and model settings", "result": "child f900375e unchanged; no model setting", "source": "Wall 11286 item 3; W1 Wall 11289 item 3"}]$j$::jsonb,
  $j$[{"seat": "W1", "result": "MATCH (n8n versions diff 9c9891d4 to 196402d0: one node modified, Alternate Merge, the E1 line only; jsCode 4a623df613eeb41ffaee69208fa9617e, 16,428 characters; child unchanged; execution 42071 stopped before the write)", "wall_id": 11289}]$j$::jsonb,
  $j${"case": "NO PROBE: only an n8n retry of a crashed execution takes the path. UNEXERCISED. A normal run must still write its Record Substitution rows.", "source": "Wall 11275 section 7; Wall 11286 item 5; Wall 11289"}$j$::jsonb,
  $j${"op_doc": "none", "engine_manual": "not yet: W3 owes the entry (section 17) now that the fix is live and read back; until then part 11.1 names the fault in the 516 REVERTED line (version 250)"}$j$::jsonb,
  'read back', $j$[10353, 11273, 11274, 11275, 11278, 11280, 11282, 11286, 11289]$j$::jsonb)
RETURNING id)
